import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 9

    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        skipinitialspace=False,
        strict=False,
    )
    parsed_rows = [list(row) for row in reader]

    if not parsed_rows:
        return {"columns": [], "rows": []}

    def header_score(row):
        if len(row) != expected_width:
            return -1
        score = 0
        normalized = []
        for value in row:
            text = value.strip()
            key = re.sub(r"[^a-z0-9]+", "", text.lower())
            normalized.append(key)
            if text:
                score += 1
            if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_ /.-]*", text or ""):
                score += 2
            if re.search(r"[A-Za-z]", text) and not re.search(r"\d", text):
                score += 1
            if re.fullmatch(r"\d+(?:[./:-]\d+)+", text):
                score -= 4
        score += len(set(normalized)) - normalized.count("")
        return score

    candidates = [
        (header_score(row), index)
        for index, row in enumerate(parsed_rows)
        if len(row) == expected_width and any(value.strip() for value in row)
    ]

    if candidates:
        best_score = max(score for score, _ in candidates)
        header_index = next(index for score, index in candidates if score == best_score)
    else:
        header_index = next(
            (index for index, row in enumerate(parsed_rows) if row),
            0,
        )

    columns = list(parsed_rows[header_index])
    if len(columns) < expected_width:
        columns.extend("" for _ in range(expected_width - len(columns)))
    elif len(columns) > expected_width:
        columns = columns[:expected_width - 1] + [
            ",".join(columns[expected_width - 1:])
        ]

    normalized_headers = [
        re.sub(r"[^a-z0-9]+", "", value.lower()) for value in columns
    ]

    def find_column(*terms):
        for index, name in enumerate(normalized_headers):
            if any(term in name for term in terms):
                return index
        return None

    type_index = find_column("producttype", "itemtype")
    description_index = find_column("productdescription", "description")
    url_index = find_column("url", "link", "website")
    comments_index = find_column("comment", "note", "remark")

    if type_index is None:
        type_index = max(0, expected_width - 4)
    if description_index is None:
        description_index = min(type_index + 1, expected_width - 1)
    if url_index is None:
        url_index = min(description_index + 1, expected_width - 1)
    if comments_index is None:
        comments_index = min(url_index + 1, expected_width - 1)

    url_pattern = re.compile(
        r"^(?:[a-z][a-z0-9+.-]*://|www\.)",
        re.IGNORECASE,
    )

    def bracket_end(fields, start, limit):
        if start >= limit:
            return start
        first = fields[start].lstrip()
        if not first.startswith(("[", "(", "{")):
            return start + 1

        pairs = {"[": "]", "(": ")", "{": "}"}
        opening = first[0]
        closing = pairs[opening]
        depth = 0

        for index in range(start, limit):
            for char in fields[index]:
                if char == opening:
                    depth += 1
                elif char == closing and depth:
                    depth -= 1
            if depth == 0:
                return index + 1

        return start + 1

    def normalize_row(row):
        row = list(row)

        if len(row) == expected_width:
            return row

        if len(row) < expected_width:
            return row + [""] * (expected_width - len(row))

        actual_url_index = None
        for index, value in enumerate(row):
            if url_pattern.match(value.strip()):
                actual_url_index = index
                break

        if (
            actual_url_index is not None
            and type_index < actual_url_index
            and url_index < expected_width
        ):
            result = [""] * expected_width

            prefix_count = min(type_index, len(row))
            for index in range(prefix_count):
                result[index] = row[index]

            type_end = bracket_end(row, type_index, actual_url_index)
            type_end = min(max(type_end, type_index + 1), actual_url_index)

            result[type_index] = ",".join(row[type_index:type_end])
            if description_index < expected_width:
                result[description_index] = ",".join(
                    row[type_end:actual_url_index]
                )
            result[url_index] = row[actual_url_index]

            trailing = row[actual_url_index + 1:]
            if comments_index < expected_width:
                result[comments_index] = ",".join(trailing)

            occupied = {
                type_index,
                description_index,
                url_index,
                comments_index,
            }
            source_index = type_index
            for target_index in range(type_index, expected_width):
                if target_index in occupied:
                    continue
                if source_index < actual_url_index:
                    result[target_index] = row[source_index]
                    source_index += 1

            return result

        merge_index = min(type_index, expected_width - 1)
        overflow = len(row) - expected_width
        end = merge_index + overflow + 1
        repaired = (
            row[:merge_index]
            + [",".join(row[merge_index:end])]
            + row[end:]
        )

        if len(repaired) < expected_width:
            repaired.extend("" for _ in range(expected_width - len(repaired)))
        elif len(repaired) > expected_width:
            repaired = repaired[:expected_width - 1] + [
                ",".join(repaired[expected_width - 1:])
            ]
        return repaired

    rows = [
        normalize_row(row)
        for row in parsed_rows[header_index + 1:]
    ]

    return {"columns": columns, "rows": rows}
